//! Stable release identity and per-process boot identity.

use rightkit_fs::digest::sha256_bytes;
use std::sync::OnceLock;

// Generated by build.rs into OUT_DIR. See the comment there: this must be an
// included source file rather than `option_env!`, or sccache serves a stale
// object and the binary ships an identity the build log says it does not have.
mod generated {
    include!(concat!(env!("OUT_DIR"), "/release_identity_generated.rs"));
}

/// The verified source tree this binary was compiled from, when one was pinned.
pub fn source_tree_sha256() -> Option<&'static str> {
    generated::SOURCE_TREE_SHA256
}

/// The commit this binary was compiled from, when one was pinned.
pub fn source_commit() -> Option<&'static str> {
    generated::SOURCE_COMMIT
}

/// Where the identity came from: git, snapshot, env, content, file or unknown.
pub fn source_kind() -> &'static str {
    generated::SOURCE_KIND
}

/// Stable across every process built from the same verified Membrane source tree.
pub fn release_generation() -> String {
    format!("sha256:{}", source_tree_sha256().unwrap_or("unknown"))
}

/// Native release target encoded without relying on Cargo's build-script-only `TARGET` value.
pub const fn target_triple() -> &'static str {
    if cfg!(all(
        target_arch = "x86_64",
        target_os = "windows",
        target_env = "msvc"
    )) {
        "x86_64-pc-windows-msvc"
    } else if cfg!(all(
        target_arch = "aarch64",
        target_os = "windows",
        target_env = "msvc"
    )) {
        "aarch64-pc-windows-msvc"
    } else if cfg!(all(target_arch = "x86_64", target_os = "macos")) {
        "x86_64-apple-darwin"
    } else if cfg!(all(target_arch = "aarch64", target_os = "macos")) {
        "aarch64-apple-darwin"
    } else {
        "unsupported"
    }
}

/// Random per process. This remains separate from release identity so restarts are observable.
pub fn service_generation() -> &'static str {
    static GENERATION: OnceLock<String> = OnceLock::new();
    GENERATION
        .get_or_init(|| {
            let mut random = [0u8; 32];
            if getrandom::fill(&mut random).is_ok() {
                format!("sha256:{}", sha256_bytes(&random))
            } else {
                format!(
                    "sha256:{}",
                    sha256_bytes(
                        format!("{}:{}", std::process::id(), crate::time::now_iso()).as_bytes()
                    )
                )
            }
        })
        .as_str()
}
